import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
public class CO3Solutions{
 static class FundsException extends Exception{FundsException(String m){super(m);}}
 static void q1(String x,double balance){try{int n=Integer.parseInt(x);if(n<=0)throw new IllegalArgumentException("Amount must be positive");if(n>balance)throw new FundsException("Insufficient balance");System.out.println("Dispensed Rs "+n);}catch(NumberFormatException e){System.out.println("Invalid number");}catch(FundsException e){System.out.println(e.getMessage());}catch(IllegalArgumentException e){System.out.println(e.getMessage());}finally{System.out.println("ATM session closed");}}
 static class ExamException extends Exception{ExamException(String m,Throwable c){super(m,c);}}
 static class StorageException extends ExamException{StorageException(String m,Throwable c){super(m,c);}}
 static void q2(){try{try{throw new IOException("Disk quota exceeded");}catch(IOException e){throw new StorageException("Could not store answer02.pdf",e);}}catch(ExamException e){System.out.println("Error: "+e.getMessage());System.out.println("Cause: "+e.getCause().getMessage());}}
 static void q3(Path d)throws IOException{Files.createDirectories(d);Path report=d.resolve("summary.txt");try(BufferedWriter w=Files.newBufferedWriter(report)){for(int i=1;i<=3;i++){Path f=d.resolve("store"+i+".txt");Files.writeString(f,"10\n20\n");try(BufferedReader r=Files.newBufferedReader(f)){String line;while((line=r.readLine())!=null)w.write(line+"\n");}}}System.out.println("Report lines: "+Files.readAllLines(report).size());}
 static class Station implements Runnable{final String name;final int count;Station(String n,int c){name=n;count=c;}public void run(){try{Thread.sleep(20+(long)(Math.random()*50));System.out.println(name+" scanned "+count);}catch(InterruptedException e){Thread.currentThread().interrupt();}}}
 static void q4()throws InterruptedException{Thread[]t={new Thread(new Station("Station-1",25)),new Thread(new Station("Station-2",30)),new Thread(new Station("Station-3",20)),new Thread(new Station("Station-4",35))};for(Thread x:t)x.start();for(Thread x:t)x.join();System.out.println("All stations complete");}
 static class SeatBooking{final boolean[]booked;int bookingsMade;SeatBooking(int n){booked=new boolean[n];}synchronized boolean book(int s){if(s<0||s>=booked.length)throw new IllegalArgumentException();if(booked[s])return false;booked[s]=true;bookingsMade++;return true;}}
 static void q5()throws InterruptedException{SeatBooking s=new SeatBooking(10);Thread[]t=new Thread[100];for(int i=0;i<t.length;i++){final int seat=i%10;t[i]=new Thread(()->s.book(seat));t[i].start();}for(Thread x:t)x.join();System.out.println("Seats sold: "+s.bookingsMade);}
 static class TokenCounter{final int[]b=new int[5];int count,in,out;synchronized void put(int x)throws InterruptedException{while(count==b.length)wait();b[in]=x;in=(in+1)%b.length;count++;notifyAll();}synchronized int take()throws InterruptedException{while(count==0)wait();int x=b[out];out=(out+1)%b.length;count--;notifyAll();return x;}}
 static void q6()throws InterruptedException{TokenCounter c=new TokenCounter();int[]sum={0,0};Thread p=new Thread(()->{try{for(int i=1;i<=20;i++)c.put(i);}catch(InterruptedException e){Thread.currentThread().interrupt();}});Thread[]cs=new Thread[2];for(int j=0;j<2;j++){final int k=j;cs[j]=new Thread(()->{try{for(int i=0;i<10;i++)sum[k]+=c.take();}catch(InterruptedException e){Thread.currentThread().interrupt();}});}p.start();for(Thread x:cs)x.start();p.join();for(Thread x:cs)x.join();System.out.println("Sum of tokens collected: "+(sum[0]+sum[1])+" (expected 210)");}
 static class ScoreTask implements Callable<Integer>{final Path p;ScoreTask(Path p){this.p=p;}public Integer call()throws Exception{int x=Integer.parseInt(Files.readString(p).trim());if(x<0||x>100)throw new IllegalArgumentException("Invalid score");return x;}}
 static void q7(Path d)throws Exception{Files.createDirectories(d);List<Path>ps=new ArrayList<>();for(int i=0;i<20;i++){Path p=d.resolve("score"+i+".txt");Files.writeString(p,i==7?"bad":String.valueOf(i*5));ps.add(p);}ExecutorService pool=Executors.newFixedThreadPool(4);int ok=0,bad=0;try{List<Future<Integer>>fs=new ArrayList<>();for(Path p:ps)fs.add(pool.submit(new ScoreTask(p)));for(Future<Integer>f:fs)try{f.get();ok++;}catch(ExecutionException e){bad++;}}finally{pool.shutdown();pool.awaitTermination(1,TimeUnit.MINUTES);}System.out.println("Success="+ok+" Failure="+bad);}
 public static void main(String[]a)throws Exception{q1("500",1000);q1("-2",1000);q1("oops",1000);q1("1500",1000);q2();Path d=Files.createTempDirectory("co3");q3(d);q4();q5();q6();q7(d.resolve("scores"));}
}